CREATE OR REPLACE DYNAMIC TABLE AGG.AGG_COMPLAINT_MONTH_SEGMENT_SEVERITY
  TARGET_LAG = '24 hours'
  WAREHOUSE  = WH_SEMANTIC_REFRESH
  COMMENT = 'Demand-driven aggregate of FCT_COMPLAINT at grain Date.FiscalYear, Date.MonthName, Date.Quarter, Complaint.Severity, Customer.CustomerSegment, Date.MonthNumber; covers 67.03% of weighted demand (1 clusters); est. 2,400 rows; ~0.0167 credits/day'
AS
SELECT d1.FISCAL_YEAR,
       d1.MONTH_NAME,
       d1.QUARTER,
       f.SEVERITY,
       c2.CUSTOMER_SEGMENT,
       d1.MONTH_NUMBER,
       SUM(f.RESOLUTION_DAYS) AS RESOLUTION_DAYS_SUM,
       COUNT(f.RESOLUTION_DAYS) AS RESOLUTION_DAYS_COUNT,
       COUNT(*) AS COMPLAINT_COUNT
FROM CORE.FCT_COMPLAINT f
JOIN CORE.DIM_DATE d1 ON f.DATE_KEY = d1.DATE_KEY
JOIN CORE.DIM_CUSTOMER c2 ON f.CUSTOMER_ID = c2.CUSTOMER_ID
GROUP BY ALL;
